// Synthetic card consumer: consent, local context, stale responses and no upload.
const {JSDOM}=require('jsdom');
const fs=require('fs');
const assert=require('assert/strict');
(async()=>{for(const file of ['ha-vacuum-water-monitor.js','custom_components/ha_vacuum_water_monitor/www/ha-vacuum-water-monitor.js']){
 const dom=new JSDOM('<html></html>',{runScripts:'dangerously',url:'http://localhost/'});
 dom.window.eval(fs.readFileSync(file,'utf8'));
 const card=dom.window.document.createElement('ha-vacuum-water-monitor');
 const device={vacuum_entity:'vacuum.demo'};
 const local={id:'local.1',device_id:'vacuum.demo',confirmed:true,observed_ml:100,area_m2:10,purpose:'training'};
 card._serverState={settings:{local_measurements:{'vacuum.demo':[local]}},tank_states:{'vacuum.demo':{last_consumption_context:{settings:{water_level:'medium'},field_sources:{water_level:'observed'}}}}};
 card.shadowRoot.innerHTML=card._buildConfirmedSharing(device);
 const sr=card.shadowRoot, enabled=sr.getElementById('cal-share-enabled'), consent=sr.getElementById('cal-share-consent'), preview=sr.getElementById('cal-export-preview'), download=sr.getElementById('cal-download'), submit=sr.getElementById('cal-submit');
 const packet=()=>({kind:'confirmed_measurement_contribution',schema_version:1,publication_consent:false,runtime_eligible:false,licence:'CC-BY-4.0',samples:[{area_m2:10,measured_ml:100}]});
 const calls=[];
 card._hass={callWS:async request=>{calls.push(request);return packet();}};
 assert.equal(enabled.checked,false);
 assert.equal(consent.checked,false);
 assert.equal(download.disabled,true);
 assert.equal(submit.hasAttribute('href'),false);
 assert.equal(await card._previewCalibration(device),false);
 assert.equal(calls.length,0);
 enabled.checked=true;
 assert.equal(await card._previewCalibration(device),true);
 assert.equal(calls[0].type,'ha_vacuum_water_monitor/contribution_preview');
 assert.deepEqual(Array.from(calls[0].sample_ids),['local.1']);
 assert.equal(JSON.parse(preview.value).publication_consent,false);
 assert.equal(download.disabled,true);
 assert.equal(submit.hasAttribute('href'),false);
 consent.checked=true;card._renderContributionConsent();
 assert.equal(JSON.parse(preview.value).publication_consent,true);
 assert.equal(download.disabled,false);
 const url=new URL(submit.href);
 assert.equal(url.hostname,'github.com');
 assert.equal(url.pathname,'/MacSiem/vacuum-consumption-data/issues/new');
 assert.deepEqual([...url.searchParams.keys()],['template']);
 assert.equal(calls.length,1,'consent and form opening do not upload');
 local.instrument='flow_meter';
 card._renderContributionConsent();
 assert.equal(download.disabled,true,'changed hidden sample metadata invalidates existing consent');
 assert.equal(consent.checked,false);
 assert.equal(submit.hasAttribute('href'),false);
 assert.equal(await card._previewCalibration(device),true);
 consent.checked=true;card._renderContributionConsent();
 consent.checked=false;card._renderContributionConsent();
 assert.equal(download.disabled,true);
 assert.equal(submit.hasAttribute('href'),false);
 enabled.checked=false;card._renderContributionConsent();
 assert.equal(preview.hidden,true);
 assert.equal(consent.checked,false);
 enabled.checked=true;
 let resolve;
 card._hass.callWS=()=>new Promise(r=>{resolve=r;});
 const pending=card._previewCalibration(device);
 local.observed_ml=101;
 resolve(packet());
 assert.equal(await pending,false,'a changed saved measurement invalidates preview');
 assert.equal(download.disabled,true);
 card._hass.callWS=async()=>{throw new Error('offline');};
 assert.equal(await card._previewCalibration(device),false);
 assert.equal(preview.hidden,true);
 const unavailable=JSON.parse(JSON.stringify(card._serverState));
 unavailable.tank_states['vacuum.demo'].last_consumption_context.field_sources.water_level='unavailable';
 unavailable.tank_states['vacuum.demo'].last_consumption_context.settings.water_level=null;
 const savedState=card._serverState;card._serverState=unavailable;
 assert.ok(card._buildMeasurementPlan(device).includes('HA signal unavailable'));
 card._serverState=savedState;
 const guidance=card._buildAccountingGuidance({initialized:true,capability:'automatic_estimate',
   accountingSource:'whole_cycle',accountingEvidence:'device_calibration',calibrationSamples:4,calibrationFactor:1.2,
   estimateBasis:'owner_device',uncertaintyPercent:50,consumptionResolution:{source:'device_calibration',method:'area',coefficient:10}});
 assert.ok(guidance.includes('Physical whole-cycle calibration'));
 assert.equal(guidance.includes('prior band'),false);
 assert.equal(guidance.includes('Factor'),false);
 const pendingGuidance=card._buildAccountingGuidance({initialized:true,capability:'automatic_estimate',stateReason:'whole_cycle_pending',
   accountingSource:'whole_cycle',consumptionResolution:{source:'device_calibration',method:'area',coefficient:10}});
 assert.ok(pendingGuidance.includes('Whole-cycle estimate pending'));
 assert.equal(pendingGuidance.includes('Physical whole-cycle calibration'),false);
 const doses=card._buildDiagnostics({cycleActionTotals:{floor_mopping:480.24,mop_wash:2550}});
 assert.ok(doses.includes('Recorded floor doses') && doses.includes('Recorded mop-wash doses'));
 assert.ok(doses.includes('nominal level anchors are separate'));

 card.shadowRoot.innerHTML=card._buildMeasurementPlan(device);
 const water=sr.querySelector('[data-measurement-field="water_level"]');
 assert.equal(water.readOnly,true,'observed HA controls stay authoritative');
 assert.equal(water.value,'medium');
 card._hass.callWS=async request=>{calls.push(request);return {saved:true};};
 assert.equal(await card._saveMeasurementPlan(device),false);
 sr.getElementById('cal-plan-confirm').checked=true;
 sr.querySelector('[data-measurement-field="wash_mode"]').value='standard';
 assert.equal(await card._saveMeasurementPlan(device),true);
 assert.equal(calls.at(-1).type,'ha_vacuum_water_monitor/set_measurement_plan');
 assert.equal(calls.at(-1).plan.settings.wash_mode,'standard');
 assert.equal(Object.hasOwn(calls.at(-1).plan.settings,'water_level'),false);
 dom.window.close();
} console.log('Confirmed measurement UI: OFF, exact preview/consent, blank intake, stale/error and prospective context PASS, both copies');})().catch(error=>{console.error(error);process.exit(1);});
